SELECT COUNT(DISTINCT u.id) FROM users u WHERE u.is_deleted = 0
AND u.status = #{status}
AND EXISTS ( SELECT 1 FROM user_roles ur JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = u.id AND r.role_code = #{role} )

SELECT u.id, u.username, u.real_name, u.email, u.phone, u.user_no, u.status, u.created_at, GROUP_CONCAT(DISTINCT r.role_code ORDER BY r.role_code SEPARATOR ',') AS role_codes FROM users u LEFT JOIN user_roles ur ON ur.user_id = u.id LEFT JOIN roles r ON r.id = ur.role_id WHERE u.is_deleted = 0
AND u.status = #{status}
AND r.role_code = #{role}
GROUP BY u.id ORDER BY u.created_at DESC LIMIT #{pageSize} OFFSET #{offset}

